function extract(src, names) {
  const out = {};
  for (const n of names) {
    const re = new RegExp('void\\s+' + n + '\\s*\\(\\s*\\)\\s*\\{');
    const m = re.exec(src);
    if (!m) { out[n] = null; continue; }
    let i = m.index + m[0].length - 1, depth = 0;
    for (; i < src.length; i++) {
      if (src[i] === '{') depth++;
      else if (src[i] === '}') { depth--; if (depth === 0) { i++; break; } }
    }
    out[n] = src.slice(m.index, i);
  }
  return out;
}

// normalize: strip comments, whitespace
function norm(s) {
  return s
    .replace(/\/\*[\s\S]*?\*\//g, '')
    .replace(/\/\/[^\n]*/g, '')
    .replace(/\s+/g, '')
    .trim();
