{"content": "const fs = require('fs');
const S = 'C:/Users/UserX/AppData/Local/Temp/s4s/';

function extract(src, names) {
  const out = {};
  for (const n of names) {
    const re = new RegExp('void\\s+' + n + '\\s*\\(\\s*\\)\\s*\\{');
    const m = re.exec(src);
    if (!m) { out[n] = null; continue; }
    let i = m.index + m[0].length - 1, d = 0;
    for (; i < src.length; i++) {
      if (src[i] === '{') d++;
      else if (src[i] === '}') { d--; if (d === 0) { i++; break; } }
    }
    out[n] = src.slice(m.index, i);
  }
  return out;
}
const names = ['front','back','left','right','sitdown','lie','toplefthand','toprighthand','dosleep'];
const O = extract(fs.readFileSync(S + 'official_v11.cpp', 'utf8'), names);
const G = extract(fs.readFileSync(S + 'gitee_main.cpp', 'utf8'), names);
const L = extract(fs.readFileSync(S + 'local_main.cpp', 'utf8'), names);

const norm = s => (s || '').replace(/\/\/[^\n]*/g, '').replace(/\s+/g, '');
const seq = s => {
  const o = [];
  const re = /servo(\d)\.(write|writeMicroseconds)\(([^)]*)\)|delay\(([^)]*)\)/g;
  let m;
  while ((m = re.exec(s || ''))) o.push(m[1] ? 's' + m[1] + '.' + m[2] + '(' + m[3].trim() + ')' : 'delay(' + m[4].trim() + ')');
  return o.join(' | ');
};

